def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "activate_water_dispenser": And([
            self.robot_has_spill_sensors,  # Robot has spill detection capability
            Not(self.drying_prepared)  # Drying mechanism is not prepared
        ]),  # Activating water dispenser without preparing drying mechanism creates spill hazard
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
